/**
 * Upsert every system template into the EmailTemplate table.
 *
 * Idempotent and safe to run on every boot:
 *  - Matches ONLY system rows (tenantId = null). Tenant overrides (non-null tenantId) are
 *    never selected or written, so custom per-tenant templates are preserved untouched.
 *  - We look the row up by (tenantId = null, name) and update in place when present, create
 *    when missing. We deliberately do NOT use prisma.upsert on the (tenantId, name) compound
 *    unique: tenantId is nullable and Postgres treats NULLs as distinct, so that path is
 *    unreliable for the null-tenant system rows.
 */
export async function seedSystemTemplates(
  prisma: PrismaClient,
): Promise<{ created: number; updated: number }> {
  let created = 0;
  let updated = 0;

  for (const t of DEFAULT_EMAIL_TEMPLATES) {
    const existing = await prisma.emailTemplate.findFirst({
      where: { tenantId: null, name: t.name },
      select: { id: true },
    });

    const data = {
      displayName: t.displayName,
      description: t.description,
      subject: t.subject,
      htmlBody: t.htmlBody,
      textBody: t.textBody,
      variables: t.variables as unknown as object,
      isSystem: true,
      isActive: true,
    };

    if (existing) {
      await prisma.emailTemplate.update({ where: { id: existing.id }, data });
      updated++;
    } else {
      await prisma.emailTemplate.create({
        data: { tenantId: null, name: t.name, ...data },
      });
      created++;
    }
  }

  return { created, updated };
}
